# Generated by build.py from recipe.yml for recipe kafka-log-in-over-tls. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--user', 'alice:s3cret', '--cert', 'server.pem', '--key', 'server.key', 'kafkas://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --cacert server.pem -u alice:s3cret -d first kafkas://127.0.0.1:8080/orders --next -s --cacert server.pem -u alice:s3cret kafkas://127.0.0.1:8080/orders } finally { Stop-Process $server0 }
